/* ── Single source of truth for all shop stat figures ─────────────────────
   Defined BEFORE ShopSelector and ShopDashboard so both can call it.
────────────────────────────────────────────────────────────────────────── */
/* Today's date as "YYYY-MM-DD" using LOCAL date parts (no UTC shift) —
   used to cap sale/purchase date inputs so future dates can't be entered. */
const localTodayISO=()=>{
  const d=new Date();
  const y=d.getFullYear();
  const mo=String(d.getMonth()+1).padStart(2,"0");
  const da=String(d.getDate()).padStart(2,"0");
  return `${y}-${mo}-${da}`;
};
const STAT_FULFILLED=new Set(["FULFILLED","EXCHANGED","REFUNDED","GOOD FEEDBACK","GOOD FEEDBACK RCVD","NEGATIVE FEEDBACK RCVD"]);
const STAT_RETURNS  =new Set(["RTRN REQSTD","RETRN RCVD","RETURN RQSTD","RETURN RCVD","EXCHANGED"]);

/* ── Instalment / linked-deal groups: finds all sales linked to the same
   deal as `sale`, across the FULL sales history. A customer's sales
   (matched by name+phone) chain together automatically based on the
   dedicated Payment Type field (Full/Advance/Part/Final) chosen when the
   sale was saved. An ADVANCE always starts a fresh deal (even resetting
   one never formally closed); a FINAL always closes the deal right after
   it's added. PART just joins whatever deal is open. FULL never joins
   anything — always its own standalone sale. Status is NOT used to
   decide grouping — the advance portion is often marked Fulfilled
   independently, long before the final payment is even recorded, which
   made status an unreliable signal. ───────────────────────────────────── */
/* Reads the new dedicated paymentType field; falls back to the old
   free-text tags for any sale not yet covered by the migration. */
const inferPaymentType=(sale)=>{
  if(sale.paymentType) return sale.paymentType;
  const tags=(sale.tag||"").split(",").map(t=>t.trim());
  if(tags.includes("Advance Sale")) return "ADVANCE";
  if(tags.includes("Final Payment Sale")) return "FINAL";
  if(tags.includes("Part Payment")) return "PART";
  return "FULL";
};
/* Same-day transactions must sort by payment role, not invoice number —
   invoice numbers reflect save order, not necessarily the logical
   Advance -> Part -> Final sequence. */
const tagPriorityG=(s)=>{
  const pt=inferPaymentType(s);
  if(pt==="ADVANCE") return 0;
  if(pt==="FINAL") return 2;
  return 1; // Part, or Full
};
const findInstalmentGroupIds=(sale,allSales)=>{
  // Manual link always wins, regardless of payment type — this is the
  // fallback for when automatic Advance/Part/Final detection misses a
  // pairing (e.g. a payment mistakenly tagged Full instead of Final).
  let manualIds=[];
  if(sale.manualLinkGroup){
    manualIds=(allSales||[]).filter(s=>s.manualLinkGroup===sale.manualLinkGroup).map(s=>s.id);
  }
  if(inferPaymentType(sale)==="FULL"){
    return manualIds.length>1 ? manualIds : [sale.id];
  }
  const phone=(sale.phone||sale.contact||"").replace(/\D/g,"").slice(-10);
  const name=(sale.customer||"").toLowerCase().trim();
  if(!phone&&!name) return manualIds.length>1 ? manualIds : [sale.id];
  const custSales=(allSales||[]).filter(s=>{
    const sPhone=(s.phone||s.contact||"").replace(/\D/g,"").slice(-10);
    const sName=(s.customer||"").toLowerCase().trim();
    return sName===name&&sPhone===phone&&inferPaymentType(s)!=="FULL";
  });
  const sorted=[...custSales].sort((a,b)=>{
    const d=(a.date||"").localeCompare(b.date||"");
    if(d!==0) return d;
    const p=tagPriorityG(a)-tagPriorityG(b);
    if(p!==0) return p;
    return (a.invoiceNo||a.id||"").localeCompare(b.invoiceNo||b.id||"");
  });
  let currentGroup=[];
  let found=null;
  let dealOpen=false;
  for(let i=0;i<sorted.length;i++){
    const s=sorted[i];
    const pt=inferPaymentType(s);
    const isAdvance=pt==="ADVANCE";
    const isFinal=pt==="FINAL";
    if(!dealOpen||isAdvance){ currentGroup=[]; dealOpen=true; }
    currentGroup.push(s);
    if(s.id===sale.id) found=currentGroup;
    if(isFinal) dealOpen=false;
  }
  const autoIds = (found&&found.length>=2) ? found.map(s=>s.id) : [sale.id];
  if(manualIds.length<2) return autoIds;
  // Merge auto-detected group with manually-linked sales
  return Array.from(new Set([...autoIds, ...manualIds]));
};

/* Outstanding balance for a group of sale IDs, based on the Expected
   Total set on whichever sale in the group is tagged Advance. Returns
   null if no Expected Total is set (nothing to check against). */
/* ── Status chain: mirrors the one in SalesPanel.jsx (files don't share
   code). Given the CURRENT status, returns which statuses are allowed to
   be selected next, keeping the workflow logically sequential. ────────── */
const getAllowedStatuses=(currentStatus,shopId)=>{
  const isIndia=shopId==="ros-india";
  const cur=(currentStatus||"PENDING").toUpperCase();
  const RETURN_RQSTD=isIndia?"RETURN RQSTD":"RTRN REQSTD";
  const RETURN_RCVD=isIndia?"RETURN RCVD":"RETRN RCVD";
  const FEEDBACK=isIndia?["GOOD FEEDBACK RCVD","NEGATIVE FEEDBACK RCVD"]:["GOOD FEEDBACK"];
  switch(cur){
    case "PENDING": return ["PENDING","FULFILLED"];
    case "FULFILLED": return ["FULFILLED",RETURN_RQSTD,RETURN_RCVD,...FEEDBACK];
    case RETURN_RQSTD: return [RETURN_RQSTD,RETURN_RCVD];
    case RETURN_RCVD: return [RETURN_RCVD,"REFUNDED","EXCHANGED"];
    case "REFUNDED": return ["REFUNDED",...FEEDBACK];
    case "EXCHANGED": return ["EXCHANGED",...FEEDBACK];
    default:
      if(FEEDBACK.includes(cur)) return [cur,RETURN_RQSTD];
      return null;
  }
};

const getGroupBalanceInfo=(groupIds,allSales)=>{
  const group=(allSales||[]).filter(s=>groupIds.includes(s.id));
  const advanceSale=group.find(s=>inferPaymentType(s)==="ADVANCE");
  const expectedTotal=advanceSale?Number(advanceSale.expectedTotal)||0:0;
  if(expectedTotal<=0) return null;
  const received=group.reduce((a,x)=>a+(Number(x.amount)||0),0);
  return {expectedTotal,received,balance:expectedTotal-received};
};

const SHOP_LABELS={"ros-selections":"ROS Selections","ros-hairlines":"ROS Hairlines","ros-india":"ROS India"};

/* ── runAudit: scans every sale in every shop for the five agreed
   categories of issues. Read-only — never modifies anything, just
   reports. Returns one flat array of findings, each tagged with which
   category it belongs to so the UI can group and count them. ────────── */
const runAudit=(salesData)=>{
  const findings=[];
  const push=(category,severity,shopId,saleId,customer,detail)=>{
    const key=`${category}__${shopId}__${saleId}`;
    findings.push({key,category,severity,shopId,saleId,customer,detail});
  };

  Object.keys(salesData||{}).forEach(shopId=>{
    const sales=salesData[shopId]||[];
    const seenGroups=new Set();

    sales.forEach(s=>{
      const status=(s.ful||s.status||"").toUpperCase();
      const dispatched=status!=="PENDING";
      const pt=inferPaymentType(s);
      const ageDays=Math.floor((Date.now()-new Date(s.date).getTime())/86400000);

      // 1. Payment integrity — dispatched without full payment
      if(dispatched){
        const groupIds=findInstalmentGroupIds(s,sales);
        const groupKey=groupIds.slice().sort().join("_");
        if(groupIds.length>1 && !seenGroups.has(groupKey)){
          seenGroups.add(groupKey);
          const bal=getGroupBalanceInfo(groupIds,sales);
          if(bal && bal.balance>0){
            push("payment","high",shopId,s.id,s.customer,
              `Dispatched with ${fmt(shopId,bal.balance)} still unpaid (expected ${fmt(shopId,bal.expectedTotal)}, received ${fmt(shopId,bal.received)})`);
          }
        }
      }

      // 2. Broken links — orphaned Advance/Part (30+ days) or orphaned Final (any age)
      if(pt==="ADVANCE"||pt==="PART"){
        const groupIds=findInstalmentGroupIds(s,sales);
        const group=sales.filter(x=>groupIds.includes(x.id));
        const hasFinal=group.some(x=>inferPaymentType(x)==="FINAL");
        if(!hasFinal && ageDays>=30){
          push("links","medium",shopId,s.id,s.customer,
            `${pt==="ADVANCE"?"Advance":"Part"} payment from ${ageDays} days ago with no closing payment yet`);
        }
      }
      if(pt==="FINAL"){
        const groupIds=findInstalmentGroupIds(s,sales);
        if(groupIds.length<2){
          push("links","medium",shopId,s.id,s.customer,
            `Marked as Final payment but no matching Advance/Part payment found`);
        }
      }

      // 3. Incomplete records
      const missing=[];
      if(!(s.phone||s.contact||"").trim()) missing.push("phone number");
      if(!(s.address||"").trim()) missing.push("address");
      if(!(s.item||"").trim()) missing.push("item");
      if(!(Number(s.amount)>0)) missing.push("amount");
      if(missing.length>0){
        push("incomplete","medium",shopId,s.id,s.customer,`Missing: ${missing.join(", ")}`);
      }
      if(dispatched && !(s.trackingNo||"").trim()){
        push("incomplete","low",shopId,s.id,s.customer,`Dispatched with no tracking number on file`);
      }
    });

    // 4. Suspected duplicates — same customer + amount + date
    const seenCombos={};
    sales.forEach(s=>{
      const key=`${(s.customer||"").toLowerCase().trim()}__${Number(s.amount)||0}__${s.date}`;
      if(!key.trim() || key.startsWith("__")) return;
      (seenCombos[key]=seenCombos[key]||[]).push(s);
    });
    Object.values(seenCombos).forEach(group=>{
      if(group.length>1){
        push("duplicates","medium",shopId,group.map(s=>s.id).join(", "),group[0].customer,
          `${group.length} sales with the same customer, amount, and date — possible duplicate entry`);
      }
    });

    // 5. Manual link consistency — linked sales with mismatched customer names
    const byManualLink={};
    sales.forEach(s=>{ if(s.manualLinkGroup) (byManualLink[s.manualLinkGroup]=byManualLink[s.manualLinkGroup]||[]).push(s); });
    Object.values(byManualLink).forEach(group=>{
      const names=new Set(group.map(s=>(s.customer||"").toLowerCase().trim()));
      if(names.size>1){
        push("consistency","high",shopId,group.map(s=>s.id).join(", "),group.map(s=>s.customer).join(" / "),
          `Manually linked sales have different customer names — please verify this link is correct`);
      }
    });
  });

  return findings;
};

const AUDIT_CATEGORIES=[
  {key:"payment",    label:"Payment Integrity",  icon:"💰", desc:"Dispatched before full payment was received"},
  {key:"links",      label:"Broken Links",       icon:"🔗", desc:"Advance/Part/Final payments that don't properly connect"},
  {key:"incomplete", label:"Incomplete Records", icon:"📋", desc:"Missing key details like phone, address, item, or tracking"},
  {key:"duplicates", label:"Suspected Duplicates",icon:"⚠️", desc:"Same customer, amount, and date entered more than once"},
  {key:"consistency",label:"Data Consistency",   icon:"🔍", desc:"Manually linked sales that don't fully match up"},
];

/* ── getSaleFY: returns FY start year for a sale using invoice suffix as ground truth ── */
const getSaleFY=(sale)=>{
  const id=String(sale.id||"");
  const m=id.match(/^[A-Z]{2,3}(\d{4})(\d)$/);
  if(m){
    const suffix=+m[2];
    const nowY=new Date().getFullYear();
    const decade=Math.floor(nowY/10)*10;
    let endY=decade+suffix;
    if(endY-nowY>5)endY-=10;
    if(nowY-endY>5)endY+=10;
    return endY-1; // FY start year e.g. 2026 for FY26-27
  }
  // Fallback: derive from date
  const dt=parseDate(sale.date);
  if(!dt)return null;
  return dt.getMonth()<3?dt.getFullYear()-1:dt.getFullYear();
};

const calcShopStats=(data=[])=>{
  const now=new Date();
  const y=now.getFullYear(),mo=now.getMonth(),d=now.getDate();
  // Current FY start year: Apr-Dec → this year, Jan-Mar → last year
  const curFYStart=mo<3?y-1:y;

  // Current FY sales only (using invoice suffix as ground truth)
  const curFYData=data.filter(s=>getSaleFY(s)===curFYStart);

  const isToday=s=>{const dt=parseDate(s.date);return dt&&dt.getFullYear()===y&&dt.getMonth()===mo&&dt.getDate()===d;};
  const isMonth=s=>{const dt=parseDate(s.date);return dt&&dt.getFullYear()===y&&dt.getMonth()===mo;};

  const isRefunded=s=>(s.ful||s.status)==="REFUNDED";
  const rev=(arr)=>arr.filter(s=>!isRefunded(s)).reduce((a,s)=>a+(Number(s.amount)||0)-(Number(s.adjAmt)||0),0);

  // Month and today filtered within current FY only
  const monthArr=curFYData.filter(s=>isMonth(s));
  const todayArr=curFYData.filter(s=>isToday(s));

  return {
    todaySales:    rev(todayArr),
    monthRev:      rev(monthArr),
    monthOrders:   monthArr.length,
    monthReturns:  monthArr.filter(s=>STAT_RETURNS.has(s.ful||s.status)).length,
    monthRefunds:  monthArr.filter(s=>isRefunded(s)).reduce((a,s)=>a+(Number(s.refundAmt)||0),0),
    // Pending: ALL time, all FY — unfulfilled is unfulfilled regardless of year
    pendingOrders: data.filter(s=>!STAT_FULFILLED.has(s.ful||s.status)).length,
    totalRev:      rev(data),
    orders:        data.length,
    fySales:       rev(curFYData),
    fyOrders:      curFYData.length,
  };
};

